mapper.select:
/*getAgentDmIssueList*/ SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PMNGTYPE' AND CODE = A.TYPE) AS SENT_TYPE_TEXT, -- 이슈상태 A.PO_NO AS SENT_PO_NO, -- 발주번호 A.BUYER AS SENT_BUYER, -- 고객사 코드 (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS SENT_BUYER_NAME, -- 고객사명 DECODE(A.PO_SEQ, '000000' , (SELECT MAX(DESCRIPTION) || ' 외 ' || DECODE(COUNT(DESCRIPTION), 1, '',COUNT(DESCRIPTION)-1 || ' 종') FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND STATUS <> 'D') , (SELECT DESCRIPTION FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ AND STATUS <> 'D') )AS SENT_DESCRIPTION, -- 품명 (SELECT PO_REMARK FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ AND STATUS <> 'D') AS SENT_PO_REMARK,-- PODT 비고 DECODE(A.PO_SEQ, '000000' , (SELECT MAX(SPECIFICATION) || ' 외 ' || DECODE(COUNT(SPECIFICATION), 1, '',COUNT(SPECIFICATION)-1 || ' 종') FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND STATUS <> 'D') , (SELECT SPECIFICATION FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ AND STATUS <> 'D') )AS SENT_SPECIFICATION, -- 규격 A.PO_SEQ AS SENT_PO_SEQ, A.DS_SEQ AS SENT_DS_SEQ, TO_CHAR(A.SEQ) AS SENT_SEQ, (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS SENT_BYCA_COMORG_CODE, DECODE(A.PO_SEQ, '000000' , (SELECT MAX(BUYER_ITEM_NO) || ' 외 ' || DECODE(COUNT(BUYER_ITEM_NO), 1, '',COUNT(BUYER_ITEM_NO)-1 || ' 종') FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND STATUS <> 'D') , (SELECT BUYER_ITEM_NO FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ AND STATUS <> 'D') )AS SENT_BUYER_ITEM_NO, -- 품목코드 A.AGENT AS SENT_AGENT FROM KEP_PO_MNG A WHERE 1=1 AND A.AGENT = #{st_com_code} /**P*/ -- 협력사 code AND A.STATUS = 'S' AND (A.PO_NO,A.PO_SEQ,A.DS_SEQ, A.SEQ) IN
'${item}'
ORDER BY A.ADD_DATE DESC
